const bus = new EventTarget()
bus.addEventListener("ping", (e: Event) => console.log("ping"))
bus.dispatchEvent(new Event("ping"))

const clicked = new Event("click", { cancelable: true })
clicked.preventDefault()
console.log(clicked.defaultPrevented)     // true
const greeting = new CustomEvent("greet", { detail: "hello" })
console.log(greeting.detail)              // hello

const controller = new AbortController()
controller.abort()
try {
	await fetch("http://example.com", { signal: controller.signal })
} catch (e) {
	console.log(e.name)   // AbortError
}
